n = int(input())
s = input().strip()

dx = {'U': 0, 'D': 0, 'R': 1, 'L': -1}
dy = {'U': 1, 'D': -1, 'R': 0, 'L': 0}

x, y = 0, 0
count = 0
pos = {(0, 0): 1}

for c in s:
    x += dx[c]
    y += dy[c]
    key = (x, y)
    if key in pos:
        count += pos[key]
        pos[key] += 1
    else:
        pos[key] = 1

print(count)
