import sys
from collections import defaultdict

def main():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    count = 0
    for i in range(n):
        x, y = 0, 0
        for j in range(i, n):
            c = s[j]
            if c == 'U':
                y += 1
            elif c == 'D':
                y -= 1
            elif c == 'R':
                x += 1
            else:
                x -= 1
            if x == 0 and y == 0:
                count += 1
    print(count)

if __name__ == "__main__":
    main()
```

